// Generated by scaffold-admin-crud — admin read surface over NotificationsRepository (repo mode)
import { Controller, Get, Param, Query, ParseUUIDPipe, UseGuards } from '@nestjs/common';
import { ApiTags, ApiOperation } from '@nestjs/swagger';
import { JwtAuthGuard } from '../../core/guards/jwt-auth.guard';
import { RolesGuard } from '../../core/guards/roles.guard';
import { Roles } from '../../core/decorators/roles.decorator';
import { NotificationsRepository } from './notifications.repository';

@ApiTags('admin/notifications')
@Controller('admin/notifications')
@UseGuards(JwtAuthGuard, RolesGuard)
@Roles('admin', '99')
export class AdminNotificationsController {
  constructor(private readonly repository: NotificationsRepository) {}

  @Get()
  @ApiOperation({ summary: 'Admin: list all notifications' })
  async list(@Query() query: Record<string, unknown>) {
    const items = await this.repository.findAll();
    return { items, total: Array.isArray(items) ? items.length : 0 };
  }

  @Get(':id')
  @ApiOperation({ summary: 'Admin: get one notifications by id' })
  async detail(@Param('id', ParseUUIDPipe) id: string) {
    return this.repository.findById(id);
  }
}
